// Every vessel the 2D anatomy draws, as a 3D course named by its hales-engine topology edge ID. The courses are the 2D figure's own (paths.copied.ts: its 64
// samples a vessel, meander included, generated by scripts/copy-b3-data.mjs), carried by the one linear map of frame2d.ts and given depth by the 2D figure's
// own tiers (frame2d.ts TIER_Z): nothing is placed by hand, warped or smoothed. A vessel's width is the 2D figure's (widthAt: vesselPx of its diameter, the
// liver's beds fixed, the arteries half, the cava three quarters, with the few named exceptions), in the same units, so it is the same width on the plate.
import { Vector3 } from 'three';
import { EDGES, JUNCTION_PIECES, PORTAL_TERRITORY, dMinOf } from '../../engine/hales/portal/topology.js';
import { ANAT_HIDDEN, BACK_EDGES, EDGE_PATH_2D, HIDDEN_EDGES, IVC_EDGES, NEEDS_C3 } from './paths.copied.ts';
import type { Vec3 } from '../anatomy/vessels.ts';
import { TIER_Z, type Tier, len3, x3, y3 } from '../frame2d.ts';

export type NetTone = 'portal' | 'sys' | 'artery';
export type { Tier };
export interface NetVessel {
  /** hales-engine topology edge ID (a piece's own ID when the engine cuts the vein where a shunt or collateral joins it) */
  id: string;
  /** the whole vein this piece belongs to (its own ID when not cut) */
  host: string;
  from: string; to: string;
  tone: NetTone;
  /** scene radius at the diameter the course was built at (`baseD`) */
  radius: number;
  label: string;
  /** centreline in flow order */
  pts: Vec3[];
  kind: string;
  tier: Tier;
  /** the diameter (mm) `radius` belongs to; the width then follows the engine's diameter by the 2D rule (`widthKind`) */
  baseD: number;
  /** 0: vesselPx of the diameter; 1: an artery (half of it, at least 1.8); 2: fixed (the liver's beds) */
  widthKind: 0 | 1 | 2;
}

interface Edge { id: string; from: string; to: string; kind: string; d?: number; dMax?: number; share?: number; label?: string; zone?: string; shunt?: string; spontaneous?: boolean }
const edges = EDGES as Edge[];
const edgeById = new Map(edges.map((e) => [e.id, e]));
const portal = PORTAL_TERRITORY as Set<string>;

// ---- widths: stage-tubes.js widthAt (anatomy, t = 0), in the figure's own units ----
const CALIBER = 1.3;
/** stage.js vesselPx: a vein's width in the figure's units from its diameter in mm. */
export const vesselPx = (dmm: number): number => CALIBER * Math.max(2.6, 2.0 * Math.pow(Math.max(0.1, dmm), 0.72));
const AP_FINE = 0.6;
export const isArteryEdge = (e: Edge): boolean => e.kind === 'artery' || e.kind === 'arteriole' || (e.kind === 'shunt' && e.shunt === 'ap');
const IVC_ONE_D = () => edgeById.get('IVC_IS')!.d!;

/** The figure's width of edge `e` at diameter `dmm`, before the per-vessel exceptions. */
export function widthPx(e: Edge, dmm: number): number {
  if (e.kind === 'liver') return e.zone === 'sin' || e.zone === 'inter' || e.zone === 'post' ? 3.6 : 5.2;
  if (isArteryEdge(e)) return Math.max(1.8, vesselPx(dmm) * 0.5 * (e.shunt === 'ap' ? AP_FINE : 1));
  let w = vesselPx(IVC_EDGES.has(e.id) ? IVC_ONE_D() : dmm) * (IVC_EDGES.has(e.id) || e.id === 'SVC_RA' || e.id === 'V_UP' ? 0.72 : 1);
  if (e.id === 'C8') w *= 0.6;
  if (e.id === 'LGV_CONF') w *= 0.85;
  return w;
}
/** The tube's smallest radius in the figure's units (stage-tubes.js tubeRadius: max(0.35, w / 2)). */
export const radiusOf = (wpx: number): number => len3(Math.max(0.35, wpx / 2));
const widthKindOf = (e: Edge): 0 | 1 | 2 => (e.kind === 'liver' ? 2 : isArteryEdge(e) ? 1 : 0);

// ---- tiers: stage.js (front / over lists, BACK_EDGES, arteries, collaterals) ----
const FRONT_IDS = new Set(['PV_TRUNK', 'PV_TRUNK_1', 'PVH_R', 'PVH_R_1', 'PVH_R_2', 'PVH_L', 'PVH_L_1', 'SMV_CONF', 'SV_CONF']);
const OVER_IDS = new Set(['TIPS', 'DIPS', 'C6', 'S_DSR', 'S_PC', 'C8', 'S_MC', 'REX']);
const hostOfPiece = new Map<string, string>();
for (const [host, pieces] of Object.entries(JUNCTION_PIECES as Record<string, string[]>)) for (const p of pieces) hostOfPiece.set(p, host);

function tierOf(e: Edge): Tier {
  if (BACK_EDGES.has(e.id)) return 'back';
  if (isArteryEdge(e)) return 'art';
  if (OVER_IDS.has(e.id)) return 'over';
  if (e.kind === 'collateral') return 'mid';
  if (e.kind === 'vein' && portal.has(e.to) && portal.has(e.from || '') || FRONT_IDS.has(e.id)) return 'front';
  return 'net';
}
const toneOf = (e: Edge): NetTone => (isArteryEdge(e) ? 'artery' : portal.has(e.from) || portal.has(e.to) ? 'portal' : 'sys');

/** The 2D course of an edge carried into the scene: x and y by the linear map, z by its tier. */
export function courseOf(id: string): Vec3[] {
  const e = edgeById.get(id)!, z = TIER_Z[tierOf(e)];
  return EDGE_PATH_2D[id]!.map(([x, y]): Vec3 => [x3(x), y3(y), z]);
}

/** The edges the figure draws as vessels (kinds the engine models but the anatomy never draws are left out: the catheter wedge beds, the one-way
 *  diode, the gut-side arterioles; surgical shunts and the stents belong to the procedures (B5)). */
export function isDrawnEdge(e: Edge): boolean {
  if (HIDDEN_EDGES.has(e.id) || ANAT_HIDDEN.has(e.id) || e.id === 'CAUD' || e.id === 'V_UP') return false;
  if (e.kind === 'wedge' || e.kind === 'diode') return false;
  if (e.kind === 'shunt') return e.id === 'AP_R' || e.id === 'AP_L';
  return true;
}

function build(): NetVessel[] {
  const out: NetVessel[] = [];
  for (const e of edges) {
    if (!isDrawnEdge(e)) continue;
    if (!EDGE_PATH_2D[e.id]) throw new Error(`no 2D course for ${e.id}`);
    const baseD = e.d ?? e.dMax ?? (dMinOf(e) || 3);
    out.push({
      id: e.id, host: hostOfPiece.get(e.id) ?? e.id, from: e.from, to: e.to, tone: toneOf(e), radius: radiusOf(widthPx(e, baseD)),
      label: e.label ?? e.id, pts: courseOf(e.id), kind: e.kind, tier: tierOf(e), baseD, widthKind: widthKindOf(e),
    });
  }
  return out;
}

/** Every drawn vessel, in topology order. */
export const NETWORK: readonly NetVessel[] = build();
export const NETWORK_BY_ID: ReadonlyMap<string, NetVessel> = new Map(NETWORK.map((v) => [v.id, v]));
/** Edge IDs the anatomy draws as vessels: what a parity row counts. */
export const DRAWN_EDGE_IDS: readonly string[] = edges.filter(isDrawnEdge).map((e) => e.id);
/** Drawn only once the paraumbilical collateral has opened (the 2D rule). */
export const NEEDS_C3_IDS = NEEDS_C3;

// ---- presence ----
export type Presence = 'shown' | 'ghost' | 'hidden';
export interface PresenceFrame { Q: ArrayLike<number>; Qf?: ArrayLike<number>; D: ArrayLike<number> }
export interface PresenceOptions { /** Blood menu: Potential collaterals (dotted routes that open with pressure) */ collaterals: boolean }
const OPEN_FRAC = 0.12, OPEN_Q = 0.3, C3_FRAC = 0.15, AP_Q = 0.3;
const indexOf = new Map(edges.map((e, i) => [e.id, i]));

/** How far a collateral has opened, 0 to 1, from its diameter between its closed and open ones (stage-frame.js recruitFrac). */
export function recruitFrac(id: string, f: PresenceFrame): number {
  const k = indexOf.get(id)!, e = edges[k]!, lo = dMinOf(e) as number, hi = e.dMax ?? lo;
  return hi > lo ? Math.min(1, Math.max(0, (f.D[k]! - lo) / (hi - lo))) : 0;
}
/** Whether a collateral is drawn open: it has grown past an eighth, or carries 0.3 mL/s. */
export function collateralOpen(id: string, f: PresenceFrame): boolean {
  const k = indexOf.get(id)!;
  return recruitFrac(id, f) > OPEN_FRAC || Math.abs((f.Qf ?? f.Q)[k]!) > OPEN_Q;
}

/** The 2D rules of stage-frame.js edgeVisible: a collateral is solid once open, a dotted thread while closed when potential collaterals are on, and nothing
 *  otherwise; the epigastric veins appear with the paraumbilical collateral; an arterioportal shunt only while it carries flow. */
export function presenceOf(v: Pick<NetVessel, 'id' | 'kind'>, f: PresenceFrame, o: PresenceOptions): Presence {
  const k = indexOf.get(v.id);
  if (k == null) return 'hidden';
  if (NEEDS_C3.has(v.id)) return recruitFrac('C3', f) > C3_FRAC ? 'shown' : 'hidden';
  if (v.kind === 'collateral') return collateralOpen(v.id, f) ? 'shown' : o.collaterals ? 'ghost' : 'hidden';
  if (v.kind === 'shunt') return (f.Qf ?? f.Q)[k]! > AP_Q ? 'shown' : 'hidden';
  return 'shown';
}
